    const foot = k.constant(1), ctl = k.G(1), lfoAmt = k.G(0), smooth = k.F('lowpass', 25, 0); // (a restarted swell can't step)
    foot.connect(ctl); lfoAmt.connect(ctl); ctl.connect(smooth);
